-- ============================================================
-- 2. CHARACTER TRANSLATIONS (two voices: Records annalistic register,
--    Romance narrative register). zh-CN then en per person.
-- ============================================================

-- Records (志) — 志载/传称 voice.
INSERT INTO character_translations(character_id,locale,name,summary,status,aliases,detail,motivation)
SELECT c.id,v.locale::locale_code,v.name,v.summary,'published',v.aliases,'','' FROM characters c JOIN (VALUES
('liu-bei','zh-CN','刘备',ARRAY['玄德']::text[],'蜀汉昭烈帝，涿郡人，早年织席贩履，后据荆益，章武元年称帝，谥昭烈皇帝。'),
('liu-bei','en','Liu Bei',ARRAY['Xuande']::text[],'Emperor Zhaolie of Shu Han, a native of Zhuo Commandery who rose from a mat-and-sandal seller to hold Jing and Yi Provinces, proclaiming himself emperor in 221.'),
('guan-yu','zh-CN','关羽',ARRAY['云长','美髯公']::text[],'蜀汉前将军，河东解人，随先主转战，镇守荆州，建安二十四年为吴将所杀。'),
('guan-yu','en','Guan Yu',ARRAY['Yunchang']::text[],'General of the Front under Shu Han, a native of Xie in Hedong who campaigned with Liu Bei and held Jing Province until his death at Wu hands in 220.'),
('zhang-fei','zh-CN','张飞',ARRAY['翼德']::text[],'蜀汉车骑将军，涿郡人，勇冠三军，章武元年为部下所害。'),
('zhang-fei','en','Zhang Fei',ARRAY['Yide']::text[],'Cavalry General of Shu Han, a native of Zhuo Commandery renowned for valor, murdered by his own subordinates in 221.'),
('cao-cao','zh-CN','曹操',ARRAY['孟德','阿瞒']::text[],'魏武帝，沛国谯人，建安年间挟天子以令诸侯，次第平定北方，谥武王，子丕追尊为帝。'),
('cao-cao','en','Cao Cao',ARRAY['Mengde']::text[],'Posthumously Emperor Wu of Wei, a native of Qiao in Pei who commanded the Han court in the emperor''s name and unified the north during the Jian''an era.'),
('sun-jian','zh-CN','孙坚',ARRAY['文台']::text[],'吴武烈皇帝（追尊），吴郡富春人，讨董联军中先登破敌，后攻刘表殁于岘山。'),
('sun-jian','en','Sun Jian',ARRAY['Wentai']::text[],'Posthumously Emperor Wulie of Wu, a native of Fuchun in Wu Commandery who spearheaded the coalition against Dong Zhuo before dying in battle against Liu Biao.'),
('sun-ce','zh-CN','孙策',ARRAY['伯符','小霸王']::text[],'吴长沙桓王（追封），孙坚长子，渡江略定江东六郡，建安五年遇刺身亡。'),
('sun-ce','en','Sun Ce',ARRAY['Bofu']::text[],'Posthumously Prince Huan of Changsha, Sun Jian''s eldest son who crossed the Yangtze to seize the six commanderies of the southeast before his assassination in 200.'),
('sun-quan','zh-CN','孙权',ARRAY['仲谋']::text[],'吴大帝，孙坚次子，承兄基业保有江东，黄龙元年称帝，在位五十余年。'),
('sun-quan','en','Sun Quan',ARRAY['Zhongmou']::text[],'Emperor Da of Wu, Sun Jian''s second son who inherited his brother''s holdings in the southeast and proclaimed himself emperor in 229, reigning over five decades.'),
('dong-zhuo','zh-CN','董卓',ARRAY['仲颖']::text[],'凉州陇西人，中平六年引兵入京废立天子，迁都长安，初平三年为部将所杀。'),
('dong-zhuo','en','Dong Zhuo',ARRAY['Zhongying']::text[],'A Liangzhou strongman from Longxi who marched his frontier troops into the capital in 189, deposed an emperor, forced the move to Chang''an, and was killed by his own officers in 192.'),
('lu-bu','zh-CN','吕布',ARRAY['奉先']::text[],'五原九原人，骁勇善战，先后依附丁原、董卓，后据徐州，建安三年为曹操所擒杀。'),
('lu-bu','en','Lu Bu',ARRAY['Fengxian']::text[],'A fierce warrior from Jiuyuan in Wuyuan who served first Ding Yuan then Dong Zhuo before holding Xuzhou, captured and executed by Cao Cao in 198.'),
('wang-yun','zh-CN','王允',ARRAY['子师']::text[],'太原祁人，汉司徒，与吕布合谋诛董卓，旋即为董卓余部所杀。'),
('wang-yun','en','Wang Yun',ARRAY['Zishi']::text[],'A native of Qi in Taiyuan who served as Minister over the Masses and conspired with Lu Bu to kill Dong Zhuo, only to be killed by Dong Zhuo''s remnant forces soon after.'),
('emperor-xian','zh-CN','汉献帝',ARRAY['刘协']::text[],'汉末代皇帝，名协，董卓所立，历经迁都、挟持，建安二十五年禅位于曹丕，封山阳公。'),
('emperor-xian','en','Emperor Xian of Han',ARRAY['Liu Xie']::text[],'The last emperor of Han, personal name Liu Xie, installed by Dong Zhuo and passed among warlords, who abdicated to Cao Pi in 220 and was enfeoffed as Duke of Shanyang.'),
('zhang-jiao','zh-CN','张角',ARRAY['大贤良师']::text[],'冀州钜鹿人，奉太平道自号大贤良师，中平元年举兵反汉，旋即病殁。'),
('zhang-jiao','en','Zhang Jiao',ARRAY['Great Teacher of Virtue']::text[],'A native of Julu in Jizhou who styled himself Great Teacher of Virtue under the Way of Great Peace, raising rebellion in 184 before dying of illness soon after.'),
('yuan-shao','zh-CN','袁绍',ARRAY['本初']::text[],'汝南汝阳人，四世三公之后，据冀青幽并四州，建安五年官渡败于曹操，未几病卒。'),
('yuan-shao','en','Yuan Shao',ARRAY['Benchu']::text[],'A native of Runan whose family had held the highest offices for four generations, ruling Ji, Qing, You, and Bing provinces until his defeat at Guandu in 200 and death soon after.'),
('yuan-shu','zh-CN','袁术',ARRAY['公路']::text[],'汝南汝阳人，袁绍从弟，据淮南，建安二年僭号称帝，建安四年兵败呕血而死。'),
('yuan-shu','en','Yuan Shu',ARRAY['Gonglu']::text[],'Yuan Shao''s cousin, holding the Huainan region, who proclaimed himself emperor in 197 and died in defeat and illness two years later.'),
('zhou-yu','zh-CN','周瑜',ARRAY['公瑾']::text[],'庐江舒人，吴中护军，佐孙策定江东，建安十三年于赤壁大破曹军，年三十六卒。'),
('zhou-yu','en','Zhou Yu',ARRAY['Gongjin']::text[],'A native of Shu in Lujiang who served as Wu''s Protector-General, helped Sun Ce secure the southeast, and broke Cao Cao''s fleet at Red Cliffs in 208 before dying at thirty-six.'),
('lu-su','zh-CN','鲁肃',ARRAY['子敬']::text[],'临淮东城人，继周瑜都督吴军，力主联刘抗曹，建安二十二年卒。'),
('lu-su','en','Lu Su',ARRAY['Zijing']::text[],'A native of Dongcheng in Linhuai who succeeded Zhou Yu as Wu''s commander and championed the alliance with Liu Bei against Cao Cao, dying in 217.'),
('zhuge-liang','zh-CN','诸葛亮',ARRAY['孔明','卧龙']::text[],'蜀汉丞相，琅邪阳都人，佐先主取荆益、定蜀汉，五次北伐，建兴十二年卒于五丈原。'),
('zhuge-liang','en','Zhuge Liang',ARRAY['Kongming','Sleeping Dragon']::text[],'Chancellor of Shu Han, a native of Yangdu in Langye who helped Liu Bei secure Jing and Yi Provinces, led five northern campaigns, and died at Wuzhang Plains in 234.'),
('zhao-yun','zh-CN','赵云',ARRAY['子龙']::text[],'常山真定人，蜀汉将领，从先主入蜀，建兴七年卒，追谥顺平侯。'),
('zhao-yun','en','Zhao Yun',ARRAY['Zilong']::text[],'A native of Zhending in Changshan who served Shu Han and followed Liu Bei into Shu, dying in 229 and posthumously titled Marquis Shunping.'),
('xu-shu','zh-CN','徐庶',ARRAY['元直']::text[],'颍川人，初事先主，后为曹操所得，仕魏至右中郎将、御史中丞。'),
('xu-shu','en','Xu Shu',ARRAY['Yuanzhi']::text[],'A native of Yingchuan who first served Liu Bei before joining Cao Cao''s court, rising to Household Counsellor and Palace Censor under Wei.'),
('sima-yi','zh-CN','司马懿',ARRAY['仲达']::text[],'河内温人，魏太傅，屡拒蜀汉北伐，嘉平元年发动高平陵之变，掌控魏廷。'),
('sima-yi','en','Sima Yi',ARRAY['Zhongda']::text[],'A native of Wen in Henei who served Wei as Grand Tutor, repeatedly repelled Shu Han''s northern campaigns, and seized control of the Wei court in the Gaoping Tombs coup of 249.'),
('cao-pi','zh-CN','曹丕',ARRAY['子桓']::text[],'魏文帝，曹操次子，延康元年受汉禅称帝，建国号魏，在位七年。'),
('cao-pi','en','Cao Pi',ARRAY['Zihuan']::text[],'Emperor Wen of Wei, Cao Cao''s second son, who accepted Han''s abdication in 220 to found Wei, reigning seven years.'),
('liu-shan','zh-CN','刘禅',ARRAY['公嗣','阿斗']::text[],'蜀汉后主，先主之子，建兴以后委政诸葛亮，炎兴元年降魏，蜀汉遂亡。'),
('liu-shan','en','Liu Shan',ARRAY['Gongsi','Adou']::text[],'The Later Ruler of Shu Han, Liu Bei''s son, who entrusted governance to Zhuge Liang before surrendering to Wei in 263, ending Shu Han.'),
('lu-xun','zh-CN','陆逊',ARRAY['伯言']::text[],'吴郡吴人，吴丞相，章武二年夷陵大破刘备，后拜上大将军，赤乌八年卒。'),
('lu-xun','en','Lu Xun',ARRAY['Boyan']::text[],'A native of Wu Commandery who served as Wu''s chancellor, crushed Liu Bei''s invasion at Yiling in 222, and later rose to Grand General before his death in 245.'),
('jiang-wei','zh-CN','姜维',ARRAY['伯约']::text[],'天水冀人，本魏将，降蜀后受诸葛亮器重，屡次北伐，景耀六年蜀亡后遇难。'),
('jiang-wei','en','Jiang Wei',ARRAY['Boyue']::text[],'A native of Ji in Tianshui, originally a Wei officer who surrendered to Shu, was groomed by Zhuge Liang, led repeated northern campaigns, and died in the chaos after Shu''s fall in 264.'),
('deng-ai','zh-CN','邓艾',ARRAY['士载']::text[],'义阳棘阳人，魏将，景元四年偷渡阴平灭蜀，旋因钟会构陷被杀。'),
('deng-ai','en','Deng Ai',ARRAY['Shizai']::text[],'A native of Jiyang in Yiyang who served Wei, secretly crossed the Yinping trail to conquer Shu in 263, and was killed soon after through Zhong Hui''s false accusations.'),
('zhong-hui','zh-CN','钟会',ARRAY['士季']::text[],'颍川长社人，魏将，与邓艾分道灭蜀，旋即谋反于成都，为乱兵所杀。'),
('zhong-hui','en','Zhong Hui',ARRAY['Shiji']::text[],'A native of Changshe in Yingchuan who served Wei, campaigned alongside Deng Ai to conquer Shu, then attempted rebellion in Chengdu and was killed by mutinous soldiers.'),
('sima-yan','zh-CN','司马炎',ARRAY['安世']::text[],'晋武帝，司马昭长子，泰始元年受魏禅称帝，太康元年灭吴统一天下。'),
('sima-yan','en','Sima Yan',ARRAY['Anshi']::text[],'Emperor Wu of Jin, Sima Zhao''s eldest son, who accepted Wei''s abdication in 265 and completed reunification by conquering Wu in 280.')
) AS v(slug,locale,name,aliases,summary) ON c.slug=v.slug AND c.work_id='10000000-0000-4000-8000-000000000006';

-- Romance (演义) — 小说叙写 voice. Diaochan is Romance-only.
INSERT INTO character_translations(character_id,locale,name,summary,status,aliases,detail,motivation)
SELECT c.id,v.locale::locale_code,v.name,v.summary,'published',v.aliases,'','' FROM characters c JOIN (VALUES
('liu-bei','zh-CN','刘备',ARRAY['玄德']::text[],'桃园结义之首，仁德爱民，三顾茅庐请出诸葛亮，终成鼎足之势。'),
('liu-bei','en','Liu Bei',ARRAY['Xuande']::text[],'The eldest of the Peach Garden oath, famed for benevolence, who thrice visited the thatched cottage to win Zhuge Liang and forge one leg of the three-way realm.'),
('guan-yu','zh-CN','关羽',ARRAY['云长','美髯公']::text[],'桃园结义二弟，青龙偃月刀镇八方，温酒斩华雄、过五关斩六将，败走麦城殒身。'),
('guan-yu','en','Guan Yu',ARRAY['Yunchang']::text[],'Second of the Peach Garden brothers, wielding the Green Dragon Crescent Blade through legendary feats before his fall at Maicheng.'),
('zhang-fei','zh-CN','张飞',ARRAY['翼德']::text[],'桃园结义三弟，豹头环眼，长坂坡一声断喝惊退曹军。'),
('zhang-fei','en','Zhang Fei',ARRAY['Yide']::text[],'Third of the Peach Garden brothers, whose thunderous roar at Changban Slope alone routed Cao Cao''s pursuing army.'),
('cao-cao','zh-CN','曹操',ARRAY['孟德','阿瞒']::text[],'乱世之奸雄，治世之能臣，青梅煮酒论英雄，挟天子以令诸侯。'),
('cao-cao','en','Cao Cao',ARRAY['Mengde']::text[],'Hero of a chaotic age and capable minister of order alike, who drank warmed wine with Liu Bei while ranking the era''s heroes, commanding all under the emperor''s name.'),
('sun-jian','zh-CN','孙坚',ARRAY['文台']::text[],'江东猛虎，讨董联军中孤军力斩华雄一军之先声，后于岘山中伏身亡。'),
('sun-jian','en','Sun Jian',ARRAY['Wentai']::text[],'The Tiger of the Southlands, first to break Dong Zhuo''s line in the punitive coalition, ambushed and killed near Mount Xian.'),
('sun-ce','zh-CN','孙策',ARRAY['伯符','小霸王']::text[],'小霸王之名震江东，神亭岭酣战太史慈，惜英年遇刺，临终托弟孙权。'),
('sun-ce','en','Sun Ce',ARRAY['Bofu']::text[],'Called the Little Conqueror for his conquest of the southeast, famed for his duel with Taishi Ci, assassinated young and entrusting his brother Sun Quan with the realm.'),
('sun-quan','zh-CN','孙权',ARRAY['仲谋']::text[],'紫髯碧眼之主，联刘抗曹定赤壁，晚年称帝，鼎立东南。'),
('sun-quan','en','Sun Quan',ARRAY['Zhongmou']::text[],'The purple-bearded, green-eyed lord who allied with Liu Bei to break Cao Cao at Red Cliffs before crowning himself emperor of the southeast.'),
('dong-zhuo','zh-CN','董卓',ARRAY['仲颖']::text[],'凶残暴虐，废少帝立献帝，火烧洛阳强迁长安，终因贪恋貂蝉死于吕布戟下。'),
('dong-zhuo','en','Dong Zhuo',ARRAY['Zhongying']::text[],'A tyrant who deposed one boy emperor for another, burned Luoyang, and forced the capital to Chang''an, undone at last by his own ward Lu Bu over the beauty Diaochan.'),
('lu-bu','zh-CN','吕布',ARRAY['奉先']::text[],'人中吕布，马中赤兔，辕门射戟解刘备之围，白门楼下丧命。'),
('lu-bu','en','Lu Bu',ARRAY['Fengxian']::text[],'Peerless in arms as his steed Red Hare was among horses, he once split a halberd''s shaft to spare Liu Bei, before meeting his end at White Gate Tower.'),
('wang-yun','zh-CN','王允',ARRAY['子师']::text[],'巧施连环计，献貂蝉离间董卓、吕布父子，助除国贼，终殉难于李傕之乱。'),
('wang-yun','en','Wang Yun',ARRAY['Zishi']::text[],'Deviser of the chain stratagem, offering Diaochan to split Dong Zhuo from his ward Lu Bu, only to perish when Dong Zhuo''s officers rose in revolt.'),
('emperor-xian','zh-CN','汉献帝',ARRAY['刘协']::text[],'冲龄践祚，历遭董卓废立、李傕郭汜之乱，终被迫禅让，汉祚四百年至此而终。'),
('emperor-xian','en','Emperor Xian of Han',ARRAY['Liu Xie']::text[],'Enthroned as a child and buffeted by Dong Zhuo''s coup and the chaos of Li Jue and Guo Si, he was at last forced to abdicate, closing four centuries of Han.'),
('zhang-jiao','zh-CN','张角',ARRAY['大贤良师']::text[],'太平道教主，散施符水聚众百万，头裹黄巾举兵，苍天已死，黄天当立。'),
('zhang-jiao','en','Zhang Jiao',ARRAY['Great Teacher of Virtue']::text[],'Leader of the Way of Great Peace, who gathered a million followers with talismans and healing water and rose in yellow-turbaned revolt under the cry that Heaven''s blue reign was dead.'),
('yuan-shao','zh-CN','袁绍',ARRAY['本初']::text[],'四世三公，门多故吏，坐拥河北之众而多谋少断，官渡一败失其根本。'),
('yuan-shao','en','Yuan Shao',ARRAY['Benchu']::text[],'Scion of a house that produced ministers for four generations, commanding Hebei''s strength yet undone at Guandu by his own indecision.'),
('yuan-shu','zh-CN','袁术',ARRAY['公路']::text[],'私藏传国玉玺，妄自称帝号仲家，众叛亲离，穷途呕血而亡。'),
('yuan-shu','en','Yuan Shu',ARRAY['Gonglu']::text[],'Having hoarded the imperial seal, he proclaimed his own short-lived dynasty, only to be abandoned by all and die in despair.'),
('diaochan','zh-CN','貂蝉',ARRAY[]::text[],'王允义女，貌若天仙，献连环计离间董卓、吕布，事成后下落不载，正史仅存董卓婢妾私通吕布一语。'),
('diaochan','en','Diaochan',ARRAY[]::text[],'Wang Yun''s adopted daughter of legendary beauty, the linchpin of the chain stratagem that turned Dong Zhuo against his ward Lu Bu; her fate afterward goes untold, and the histories preserve only a single line about a maidservant''s affair.'),
('zhou-yu','zh-CN','周瑜',ARRAY['公瑾']::text[],'江东美周郎，精通音律，赤壁一役借东风连环破曹，既生瑜何生亮。'),
('zhou-yu','en','Zhou Yu',ARRAY['Gongjin']::text[],'The southeast''s handsome Zhou Lang, a master of music, who used the borrowed wind to break Cao Cao''s chained fleet, lamenting on his deathbed why fate paired him against Zhuge Liang.'),
('lu-su','zh-CN','鲁肃',ARRAY['子敬']::text[],'忠厚长者，独排众议促成孙刘联盟，单刀会周旋于关羽之间。'),
('lu-su','en','Lu Su',ARRAY['Zijing']::text[],'An honest elder statesman who alone pressed for the Sun-Liu alliance and once met Guan Yu at a single-blade parley to press Wu''s claim to Jing Province.'),
('zhuge-liang','zh-CN','诸葛亮',ARRAY['孔明','卧龙']::text[],'隐居隆中的卧龙先生，三顾茅庐始出山，草船借箭、七擒孟获、六出祁山，鞠躬尽瘁。'),
('zhuge-liang','en','Zhuge Liang',ARRAY['Kongming','Sleeping Dragon']::text[],'The Sleeping Dragon of Longzhong, drawn from seclusion by three visits, who borrowed arrows with straw boats, freed Meng Huo seven times, and spent himself utterly across six campaigns through Qishan.'),
('zhao-yun','zh-CN','赵云',ARRAY['子龙']::text[],'浑身是胆的常山赵子龙，长坂坡单骑救主，七进七出如入无人之境。'),
('zhao-yun','en','Zhao Yun',ARRAY['Zilong']::text[],'Zhao Zilong of Changshan, all courage, who rode alone into Cao Cao''s army at Changban to rescue the infant heir, cutting through seven times as if through empty ground.'),
('xu-shu','zh-CN','徐庶',ARRAY['元直']::text[],'先主初期军师，因母被曹操赚去而身在曹营心在汉，临别荐诸葛亮出山。'),
('xu-shu','en','Xu Shu',ARRAY['Yuanzhi']::text[],'Liu Bei''s early strategist, lured to Cao Cao''s camp when his mother was taken hostage, leaving with a vow of silence and a parting recommendation of Zhuge Liang.'),
('sima-yi','zh-CN','司马懿',ARRAY['仲达']::text[],'深沉隐忍的魏之权臣，与诸葛亮对峙渭南，装病赚曹爽，终为晋室奠基。'),
('sima-yi','en','Sima Yi',ARRAY['Zhongda']::text[],'Wei''s deeply patient power broker, who faced Zhuge Liang across the Wei River, feigned illness to disarm Cao Shuang, and laid the foundation for the house of Jin.'),
('cao-pi','zh-CN','曹丕',ARRAY['子桓']::text[],'曹操之子，逼汉献帝禅位篡汉建魏，七步成诗煮豆燃萁责弟曹植。'),
('cao-pi','en','Cao Pi',ARRAY['Zihuan']::text[],'Cao Cao''s son, who forced Emperor Xian''s abdication to found Wei, and famously demanded his brother Cao Zhi compose a poem in seven steps under threat of death.'),
('liu-shan','zh-CN','刘禅',ARRAY['公嗣','阿斗']::text[],'扶不起的阿斗，长坂坡赵云怀中救出，晚年宠信黄皓，乐不思蜀而降。'),
('liu-shan','en','Liu Shan',ARRAY['Gongsi','Adou']::text[],'The child once rescued at Changban in Zhao Yun''s arms, grown into a ruler swayed by the eunuch Huang Hao, who surrendered and famously professed he did not miss Shu.'),
('lu-xun','zh-CN','陆逊',ARRAY['伯言']::text[],'白衣书生挂帅，夷陵一把火烧连营七百里，大破刘备。'),
('lu-xun','en','Lu Xun',ARRAY['Boyan']::text[],'A scholarly-seeming commander who defeated Liu Bei by setting his linked camps ablaze across seven hundred li at Yiling.'),
('jiang-wei','zh-CN','姜维',ARRAY['伯约']::text[],'继承诸葛亮遗志，九伐中原，蜀亡后诈降图谋复国，兵败自刎。'),
('jiang-wei','en','Jiang Wei',ARRAY['Boyue']::text[],'Heir to Zhuge Liang''s ambitions, he launched nine campaigns north, and after Shu''s fall attempted a feigned surrender to restore it before taking his own life in defeat.'),
('deng-ai','zh-CN','邓艾',ARRAY['士载']::text[],'魏之名将，偷渡阴平七百里无人之境，直取成都逼降后主。'),
('deng-ai','en','Deng Ai',ARRAY['Shizai']::text[],'A celebrated Wei general who crossed the trackless seven-hundred-li Yinping trail to strike Chengdu directly and force Liu Shan''s surrender.'),
('zhong-hui','zh-CN','钟会',ARRAY['士季']::text[],'才智过人的魏之谋主，构陷邓艾夺其功，据成都谋反，事败身死。'),
('zhong-hui','en','Zhong Hui',ARRAY['Shiji']::text[],'A brilliant Wei strategist who framed Deng Ai to steal credit for Shu''s fall, then rebelled at Chengdu, only to perish when the plot collapsed.'),
('sima-yan','zh-CN','司马炎',ARRAY['安世']::text[],'司马昭之子，代魏建晋，终遣王濬楼船下益州，三分归于一统。'),
('sima-yan','en','Sima Yan',ARRAY['Anshi']::text[],'Sima Zhao''s son, who founded Jin in Wei''s place and at last sent Wang Jun''s towered warships down the Yangtze to close a century of division.')
) AS v(slug,locale,name,aliases,summary) ON c.slug=v.slug AND c.work_id='10000000-0000-4000-8000-000000000007';

-- ============================================================
