JOIN characters c ON c.work_id=g.work_id
JOIN (VALUES
('house-of-liu','liu-bei'),
('house-of-liu','liu-shan'),
('shu-generals','guan-yu'),
('shu-generals','zhang-fei'),
('shu-generals','zhao-yun'),
('house-of-cao','cao-cao'),
('house-of-cao','cao-pi'),
('house-of-sun','sun-jian'),
('house-of-sun','sun-ce'),
('house-of-sun','sun-quan'),
('liangzhou-faction','dong-zhuo'),
('liangzhou-faction','lu-bu'),
('han-court','wang-yun'),
('han-court','emperor-xian'),
('yellow-turbans','zhang-jiao'),
('hebei-faction','yuan-shao'),
('hebei-faction','yuan-shu'),
('wu-commandery','zhou-yu'),
('wu-commandery','lu-su'),
('wu-commandery','lu-xun'),
('shu-chancellery','zhuge-liang'),
('shu-chancellery','xu-shu'),
('shu-chancellery','jiang-wei'),
('wei-strategists','sima-yi'),
('wei-strategists','deng-ai'),
('wei-strategists','zhong-hui'),
('house-of-sima','sima-yi'),
('house-of-sima','sima-yan')
) AS v(group_slug,char_slug) ON g.slug=v.group_slug AND c.slug=v.char_slug
WHERE g.work_id IN ('10000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000007');

