-- ============================================================
-- 5. LOCATION TRANSLATIONS (one shared summary per slug, applied to both
--    works' rows in a single pass; detail/other prose fields left to
--    later content agents).
-- ============================================================

INSERT INTO location_translations(location_id,locale,name,summary,status)
SELECT l.id,v.locale::locale_code,v.name,v.summary,'published' FROM locations l JOIN (VALUES
('luoyang','zh-CN','洛阳','东汉都城，董卓挟献帝西迁前，天下政令所出之地。'),
('luoyang','en','Luoyang','The capital of Eastern Han, the seat from which imperial edicts issued before Dong Zhuo forced the court west.'),
('changan','zh-CN','长安','西汉旧都，董卓挟献帝西迁于此，后又历李傕郭汜之乱。'),
('changan','en','Chang''an','The former Western Han capital, where Dong Zhuo relocated the court and which later endured the chaos of Li Jue and Guo Si.'),
('xuchang','zh-CN','许昌','曹操迎献帝定都于此，挟天子以令诸侯的政治中心。'),
('xuchang','en','Xuchang','Where Cao Cao installed Emperor Xian, the political center from which he commanded the realm in the emperor''s name.'),
('yecheng','zh-CN','邺城','曹操受封魏公、魏王后的根据地，邺下文人集团荟萃之所。'),
('yecheng','en','Ye','Cao Cao''s power base after his enfeoffment as Duke then King of Wei, and a gathering place for the Ye literary circle.'),
('chengdu','zh-CN','成都','蜀汉都城，刘备称帝、诸葛亮理政之所。'),
('chengdu','en','Chengdu','The capital of Shu Han, where Liu Bei proclaimed himself emperor and Zhuge Liang governed the state.'),
('jianye','zh-CN','建业','孙吴都城，孙权定都于此，六朝古都之始。'),
('jianye','en','Jianye','The capital of Eastern Wu, established by Sun Quan, marking the first of the later Six Dynasties capitals at this site.'),
('zhuo-commandery','zh-CN','涿郡','刘备、张飞故里，桃园结义传说所系之地。'),
('zhuo-commandery','en','Zhuo Commandery','The home commandery of Liu Bei and Zhang Fei, traditionally linked to the legend of the Peach Garden oath.'),
('hulao-pass','zh-CN','虎牢关','关东联军讨董会战之关隘，三英战吕布传说发生地。'),
('hulao-pass','en','Hulao Pass','The pass where the anti-Dong Zhuo coalition gave battle, traditionally the site where three heroes fought Lu Bu together.'),
('changshe','zh-CN','长社','黄巾之乱中皇甫嵩火攻破敌之地，钟会故里。'),
('changshe','en','Changshe','Where Huangfu Song broke the Yellow Turbans with a fire attack, and the home county of Zhong Hui.'),
('wancheng','zh-CN','宛城','曹操讨张绣受挫、失爱将典韦长子曹昂之地。'),
('wancheng','en','Wancheng','Where Cao Cao''s campaign against Zhang Xiu went awry, costing him his guard Dian Wei and his son Cao Ang.'),
('xuzhou','zh-CN','徐州','陶谦、刘备、吕布相继据守的中原要冲。'),
('xuzhou','en','Xuzhou','A strategic crossroads of the central plains held in turn by Tao Qian, Liu Bei, and Lu Bu.'),
('xiapi','zh-CN','下邳','吕布最后的据点，白门楼授首于此。'),
('xiapi','en','Xiapi','Lu Bu''s final stronghold, where he was executed at White Gate Tower.'),
('guandu','zh-CN','官渡','曹操以弱胜强大破袁绍之决定性战场。'),
('guandu','en','Guandu','The decisive battlefield where Cao Cao, though outnumbered, broke Yuan Shao''s army.'),
('longzhong','zh-CN','隆中','诸葛亮躬耕隐居、刘备三顾茅庐求见之地。'),
('longzhong','en','Longzhong','Where Zhuge Liang farmed in seclusion before Liu Bei sought him out with three visits.'),
('xinye','zh-CN','新野','刘备依附刘表期间的驻地，博望坡火攻曹军之地邻近。'),
('xinye','en','Xinye','Liu Bei''s base while under Liu Biao''s protection, near where the fire attack at Bowang Slope was staged.'),
('jiangling','zh-CN','江陵','荆州治所，赤壁战后孙刘曹三方争夺的战略要地。'),
('jiangling','en','Jiangling','The seat of Jing Province, a strategic prize contested by Wei, Shu, and Wu after Red Cliffs.'),
('xiangyang','zh-CN','襄阳','刘表荆州治所，荆襄名士荟萃之地。'),
('xiangyang','en','Xiangyang','Liu Biao''s seat in Jing Province and a gathering place for the region''s notable scholars.'),
('fancheng','zh-CN','樊城','与襄阳隔江相望，关羽水淹七军围曹仁之地。'),
('fancheng','en','Fancheng','Facing Xiangyang across the river, where Guan Yu flooded seven armies besieging Cao Ren.'),
('chibi','zh-CN','赤壁','孙刘联军大破曹军水师之战场，奠定三分天下之势。'),
('chibi','en','Red Cliffs','The battlefield where the allied Sun-Liu fleet broke Cao Cao''s navy, setting the terms of the coming three-way division.'),
('wulin','zh-CN','乌林','长江北岸曹军水寨所在，与赤壁隔江对峙。'),
('wulin','en','Wulin','The site on the Yangtze''s north bank where Cao Cao''s fleet camped, facing Red Cliffs across the river.'),
('chaisang','zh-CN','柴桑','孙权前期治所，赤壁战前孙刘联盟商定之地。'),
('chaisang','en','Chaisang','Sun Quan''s early seat, where the Sun-Liu alliance against Cao Cao was settled before Red Cliffs.'),
('hefei','zh-CN','合肥','曹魏与孙吴反复攻伐的东南屏障，逍遥津之战发生地。'),
('hefei','en','Hefei','Wei''s southeastern bulwark against repeated Wu offensives, site of the Battle of Xiaoyao Ford.'),
('ruxukou','zh-CN','濡须口','孙权与曹操多次相持水战之江防要口。'),
('ruxukou','en','Ruxukou','A river-mouth defense where Sun Quan and Cao Cao repeatedly faced off in naval standoffs.'),
('hanzhong','zh-CN','汉中','刘备称汉中王之地，蜀汉北伐的前进基地。'),
('hanzhong','en','Hanzhong','Where Liu Bei took the title King of Hanzhong, and the forward base for Shu Han''s northern campaigns.'),
('dingjun-mountain','zh-CN','定军山','黄忠斩夏侯渊之战场，诸葛亮遗命归葬于此。'),
('dingjun-mountain','en','Mount Dingjun','The battlefield where Huang Zhong slew Xiahou Yuan, and the mountain where Zhuge Liang asked to be buried.'),
('maicheng','zh-CN','麦城','关羽兵败突围、终至被擒殒命之地。'),
('maicheng','en','Maicheng','Where Guan Yu, defeated and encircled, attempted to break out before his capture and death.'),
('baidicheng','zh-CN','白帝城','刘备夷陵败退后驻跸之地，托孤诸葛亮于此。'),
('baidicheng','en','Baidicheng','Where Liu Bei withdrew after his defeat at Yiling and entrusted his heir to Zhuge Liang on his deathbed.'),
('yiling','zh-CN','夷陵','刘备伐吴大败、陆逊火烧连营之战场。'),
('yiling','en','Yiling','The battlefield where Liu Bei''s campaign against Wu collapsed as Lu Xun burned his linked camps.'),
('jieting','zh-CN','街亭','马谡违令失守之地，诸葛亮首次北伐因此受挫。'),
('jieting','en','Jieting','Where Ma Su''s disregard of orders lost the position, stalling Zhuge Liang''s first northern campaign.'),
('chencang','zh-CN','陈仓','诸葛亮二次北伐强攻不下、郝昭据守之坚城。'),
('chencang','en','Chencang','The fortified city Zhuge Liang failed to take in his second campaign, held firm by Hao Zhao.'),
('wuzhang-plains','zh-CN','五丈原','诸葛亮最后一次北伐屯兵对峙之地，病逝于此。'),
('wuzhang-plains','en','Wuzhang Plains','Where Zhuge Liang made his final camp facing Wei in his last campaign, and where he died.'),
('jiange','zh-CN','剑阁','蜀地北面天险，姜维退守以拒钟会大军之地。'),
('jiange','en','Jiange','A natural stronghold guarding Shu''s northern approach, where Jiang Wei made his stand against Zhong Hui''s army.'),
('mianzhu','zh-CN','绵竹','诸葛瞻父子拒邓艾力战殉国之地。'),
('mianzhu','en','Mianzhu','Where Zhuge Zhan and his son died fighting Deng Ai''s advance.'),
('shouchun','zh-CN','寿春','淮南重镇，袁术僭号称帝之都，后为淮南三叛屡次据守。'),
('shouchun','en','Shouchun','A major stronghold in Huainan where Yuan Shu proclaimed himself emperor, later held repeatedly during the Huainan rebellions.'),
('guangzong','zh-CN','广宗','皇甫嵩击破黄巾主力、张角病殁之地。'),
('guangzong','en','Guangzong','Where Huangfu Song crushed the main Yellow Turban force, and where Zhang Jiao died of illness.'),
('jiangxia','zh-CN','江夏','荆州东部要郡，刘表旧治，赤壁战前刘备一度依附之地。'),
('jiangxia','en','Jiangxia','An eastern commandery of Jing Province under Liu Biao, where Liu Bei briefly took refuge before Red Cliffs.'),
('puyang','zh-CN','濮阳','吕布与曹操反复争夺兖州治所，曹操险遭活擒之地。'),
('puyang','en','Puyang','The seat of Yan Province contested repeatedly by Lu Bu and Cao Cao, where Cao Cao himself nearly was captured.'),
('xiaopei','zh-CN','小沛','刘备寄寓吕布篱下、屡失屡得的临时据点。'),
('xiaopei','en','Xiaopei','A temporary base Liu Bei repeatedly lost and regained while sheltering under Lu Bu''s uneasy protection.')
) AS v(slug,locale,name,summary) ON l.slug=v.slug
WHERE l.work_id IN ('10000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000007');

COMMIT;


